  const openCollection = async row => { const videos = await apiV3(`/admin/catalogue/collections/${row.id}/videos`); setCollectionDetail({ ...row, videoIds: videos.records.map(video => video.legacy_id).join(', ') }); };
  const change = (field, value) => setDetail({ ...detail, record: { ...detail.record, [field]: value } });
  const save = async () => { const record = detail.record; const patch = { title: record.title, name: record.name, display_name: record.display_name, slug: record.slug, description: record.description, bio: record.bio, v3_lifecycle: record.v3_lifecycle }; await apiV3(`/admin/catalogue/${singular}/${record.legacy_id}`, { method: 'PATCH', body: JSON.stringify(patch) }); await open(record); await load(); };
  const rows = kind === 'collections' ? collections : data.records;
  const createCollection = async event => { event.preventDefault(); if (!collectionTitle.trim()) return; try { await apiV3('/admin/catalogue/collections', { method: 'POST', body: JSON.stringify({ title: collectionTitle }) }); setCollectionTitle(''); await load(); } catch (e) { setError(e.message); } };
  const saveCollection = async () => { try { await apiV3(`/admin/catalogue/collections/${collectionDetail.id}`, { method: 'PATCH', body: JSON.stringify(collectionDetail) }); const video_ids = collectionDetail.videoIds.split(',').map(value => value.trim()).filter(Boolean); await apiV3(`/admin/catalogue/collections/${collectionDetail.id}/videos`, { method: 'PUT', body: JSON.stringify({ video_ids }) }); await load(); setCollectionDetail(null); } catch (e) { setError(e.message); } };
